   "sum": "\u4e94\u4e2a\u90fd\u5f88\u7b80\u5355\u7684 Serum 2 \u4f4e\u97f3\u8f6e\u6d41\u51fa\u73b0\uff1aCompressed Sine Bass\uff08\u81ea\u7ed8\u6b63\u5f26 + 1/4 Envelope LFO \u540c\u65f6\u63a8\u97f3\u91cf\u548c\u6ee4\u6ce2 + Rock Amp 23%\uff09\u3001Womp\uff08\u65b9\u6ce2 + Band Pass 24\uff0c1/8 LFO \u63a8\u97f3\u91cf\u3001Sub \u548c \u00b140% \u6ee4\u6ce2\uff0c\u6bcf\u4e2a\u97f3\u7b26\u4e00\u6b21\u6df7\u54cd throw\uff09\u3001Sustain Bass\uff08\u7b2c 5 \u6cdb\u97f3 46% \u7684\u81ea\u7ed8\u6b63\u5f26 + AC hum 18% + Pitch Bend \u4e0b\u5f2f\uff09\u3001808\uff08\u53ea\u52a0\u7b2c 3 \u6cdb\u97f3\uff0cLFO \u5355\u6781\u63a8 Coarse Pitch 7%\uff0cAsym \u5931\u771f\uff09\u3001FM Bass\uff08\u9759\u97f3\u7684 HarmonicSeries \u505a Phase Distortion 26%\uff0c\u6b63\u5f26 Sub \u76f4\u51fa\uff0c\u4e0a\u5c42\u9ad8\u901a 150 Hz\uff09\u3002\u9f13\u662f\u53bb\u6389\u8d77\u97f3\u7684\u53e0\u5c42\u519b\u9f13\u548c Auto Pan \u505a\u97f3\u91cf\u5fae\u5dee\u7684 hat\uff0c\u4fa7\u94fe 88 ms \u786c\u5207\uff1bDuduk\u3001\u964d\u5230 F \u7684 hijaz \u65cb\u5f8b\u548c\u4eba\u58f0\u94fa\u6210\u6df7\u54cd\u5e8a\u3002",
