   "sum": "\u89c6\u9891\u7684\u7ed3\u8bba\u662f\u56db\u6761\u4e3b\u7ebf\uff1aR&B \u5f53\u4e3b\u5e72\uff0c\u51e0\u4e4e\u6bcf\u9996\u7528 A \u6bb5\uff08\u7a00\u758f\u5b9a\u6c14\u6c1b\uff09+ B \u6bb5\uff08\u58f0\u5899\u6216 beat switch\uff09\u7684\u4e24\u6bb5\u5f0f\uff0c\u8bb0\u5fc6\u62fc\u8d34\uff08\u8bed\u97f3\u3001\u5347\u8c03\u4eba\u58f0\u3001\u8001\u6b4c\u5f15\u7528\u3001\u590d\u73b0\u7684\u7535\u94a2\u5faa\u73af\uff09\u628a\u4e13\u8f91\u4e32\u6210\u4e00\u4ef6\u4f5c\u54c1\uff0c\u6bcf\u4e2a\u5408\u4f5c\u8005\u90fd\u5e26\u7740\u7ecf\u5178\u53c2\u7167\u3002\u548c\u58f0\u4e0a\u4e09\u5904\uff1aNikes \u7684 Cm/D\u266d\uff08= D\u266dmaj9\u266f11\uff0c\u53ea\u52a8\u4e00\u4e2a\u58f0\u90e8\uff09\uff0cPink + White \u7684 Cmaj7 \u2192 Bm7 \u2192 Amaj7\uff08\u5e73\u79fb\u5927\u4e03\uff0cBm7 \u5f53\u67a2\u7ebd\u4ece G \u8f6c\u5230 A\uff09\uff0cSolo / Godspeed \u7684\u798f\u97f3\u659c\u6760\u548c\u5f26\u4e0e IV \u2192 I\u3002\u5236\u4f5c\u4e0a\uff1a\u6574\u5957\u9f13\u6302 1/8 delay\u3001\u65cb\u8f6c\u97f3\u7bb1\u5409\u4ed6\u30016/8 + swing + \u9ad8\u97f3\u533a\u8d1d\u65af\u30013 \u5bf9 2 \u94a2\u7434\u94a9\u5b50\u3001\u4e00\u628a\u5409\u4ed6\u6f14\u8282\u594f\u7ec4\u3001\u5207\u7247\u91cd\u62fc\u5409\u4ed6\u3001\u53cd\u5411\u8e29\u9572\u505a swing\u3001\u7535\u8bdd EQ \u4eba\u58f0\u3002\u9644 7 \u4e2a Live \u914d\u65b9\u30016 \u4e2a\u7ec3\u4e60\u548c\u5b57\u5e55\u4eba\u540d\u6821\u6b63\u3002",
