   "sum": "\u4e24\u4e2a\u4e0d\u5728\u540c\u4e00\u4e2a\u8c03\u7684\u548c\u5f26 Cm11 \u548c E\u266dm11 \u5171\u4eab E\u266d\u3001F\u3001B\u266d\u3002\u7528 B\u266d \u505a\u4e24\u4e2a\u516b\u5ea6\u7684\u9876\u97f3\uff0cCm11 \u7684\u4e09\u97f3\u6324\u8fdb D \u548c F \u4e4b\u95f4\u5236\u9020\u5c0f\u4e8c\u5ea6\uff0cE\u266dm11 \u7167\u955c\u5b50\uff1aA\u266d \u4e0b\u79fb\u7ed9\u9876\u97f3\u7559\u7a7a\u3001G\u266d \u4e0a\u79fb\u8d34\u7740 F\uff1b\u58f0\u90e8\u91cc B\u266d\u3001F \u4fdd\u6301\uff0cG\u2192A\u266d\u3001D\u2192D\u266d \u53cd\u5411\u8fdb\u884c\u3002\u8282\u594f\u4e0a Cm11 \u4e00\u5c0f\u8282\u8d77\u8df3\u3001E\u266dm11 \u505c\u4e09\u5c0f\u8282\uff0c\u9664\u7b2c\u4e00\u4e2a\u548c\u5f26\u5916\u5168\u90e8\u63d0\u524d\u5230 &4\uff0c\u6bcf\u5c0f\u8282\u7b2c 3 \u62cd\u91cd\u51fb B\u266d\uff1b\u7b2c 8 \u5c0f\u8282\u53ea\u7528\u5171\u540c\u97f3\u5199\u65cb\u5f8b\uff0c\u7b2c 16 \u5c0f\u8282\u628a\u6700\u540e\u4e24\u4e2a\u97f3\u53cd\u8fc7\u6765\u3002\u9f13\u7684\u6bcf\u4e00\u4e0b\u90fd\u5bf9\u9f50\u548c\u5f26\u6216\u65cb\u5f8b\uff0c\u8d1d\u65af\u5728 E\u266dm11 \u4e0a\u5f3a\u8c03 F\uff0c\u6697\u6307\u56de C \u5c0f\u8c03\u4e94\u58f0\u3002\u53e6\u9644 m11 \u5e73\u79fb\u8ddd\u79bb\u4e0e\u5171\u540c\u97f3\u6570\u7684\u901f\u67e5\u8868\u3002",
