   "sum": "\u628a\u516b\u5ea6\u5f53\u955c\u5b50\uff0c\u6839\u97f3\u53ea\u6709\u516d\u4e2a\u53bb\u5904\uff1a1\u20136 \u4e2a\u534a\u97f3\uff0c7\u201311 \u53ea\u662f\u7ffb\u8f6c\uff0c\u4e09\u5168\u97f3\u662f\u53cd\u5c04\u70b9\uff1b\u540c\u4e00\u8ddd\u79bb\u7684\u4e0a\u884c\u548c\u4e0b\u884c\u662f\u975e\u540c\u5375\u53cc\u80de\u80ce\uff0c\u548c\u5f26\u7c7b\u578b\u53ea\u662f\u670d\u88c5\u3002\u4e09\u96c6\u6b63\u597d\u843d\u5728\u7f57\u76d8\u4e0a\uff1a\u5c0f\u4e09\u5ea6\uff08E\u266dm11\uff0c3 \u4e2a\u5171\u540c\u97f3\uff09\u3001\u5927\u4e09\u5ea6\uff08A\u266dm11\uff0c2 \u4e2a\uff09\u3001\u534a\u97f3\uff08D\u266dm11\uff0c1 \u4e2a\uff09\u3002\u793a\u8303\u628a\u6700\u660e\u663e\u7684\u534a\u97f3\u5e73\u79fb Cm11 \u2192 D\u266dm11 \u85cf\u8d77\u6765\uff1a\u552f\u4e00\u7684\u5171\u540c\u97f3 E\u266d \u5bf9\u9f50\u5230 E\u266d3 \u5e76\u7528\u53cd\u62cd\u91cd\u590d\uff0c\u4e24\u4fa7\u653e\u955c\u50cf\u5c0f\u4e8c\u5ea6\uff08D \u5728\u4e0b\u3001E \u5728\u4e0a\uff09\uff1b\u9876\u97f3 G \u2192 G\u266d \u548c\u6839\u97f3 C \u2192 D\u266d \u53cd\u5411\uff1bF \u4e0b\u79fb\u8ba9\u9876\u97f3\u7559\u7a7a\uff0cCm11 \u53d8\u6210\u56db\u5ea6\u53e0\u7f6e\u3002\u6700\u540e\u6839\u97f3\u4ea4\u7ed9\u8d1d\u65af\uff0c\u7528 F \u2192 G \u2192 A\u266d \u2192 G\u266d \u2192 F \u5728\u4f4e\u97f3\u533a\u5199\u526f\u65cb\u5f8b\u3002",
