   "sum": "\u79bb\u5f00 I\u2013IV\u2013V\u2013vi \u7684\u201c\u8bb2\u6545\u4e8b\u201d\uff0c\u53ea\u5728\u4e24\u4e2a\u548c\u58f0\u533a\u57df\u4e4b\u95f4\u6447\u6446\u3002\u6bcf\u4e2a\u5c0f\u548c\u5f26\u90fd\u914d Dorian\uff08\u5927\u8c03\u964d 3\u30017 \u7ea7\uff1b\u4ee5 C \u4e3a\u4e3b\u97f3\u7684\u4e03\u79cd\u8c03\u5f0f\u5404\u501f\u54ea\u4e2a\u5927\u8c03\u7684\u97f3\uff09\u3002Cm7 \u2194 D\u266dm7 \u6ca1\u6709\u5171\u540c\u548c\u5f26\u97f3\uff0c\u4f46\u4e24\u4e2a Dorian \u5171\u4eab E\u266d\u3001B\u266d\uff1a\u5f3a\u8c03\u5b83\u4eec\uff0c\u540c\u4e00\u4e2a\u97f3\u5728 Cm7 \u4e0a\u662f\u4e09\u97f3\u3001\u4e03\u97f3\uff0c\u5728 D\u266dm7 \u4e0a\u662f\u4e5d\u97f3\u3001\u5341\u4e09\u97f3\u3002\u6574\u9996\u7528 Fm9 \u2194 E\u266dm9\uff1aE\u266dm9 \u63d0\u524d\u4e00\u4e24\u4e2a\u5341\u516d\u5206\uff0cFm9 \u7684\u91cd\u590d\u5ef6\u540e\u4e00\u4e2a\u5341\u516d\u5206\uff1b\u7b2c\u4e8c\u6b21\u9876\u97f3\u964d\u516b\u5ea6\u6362\u65cb\u5f8b\uff1bEm9 \u534a\u97f3\u7ecf\u8fc7\u56de\u5230 F\uff1b\u6eda\u594f\u3001\u53e0\u516b\u5ea6\u52a0\u7436\u97f3\u3002\u5f26\u4e50\u62c9\u5171\u540c\u97f3 B\u266d\uff0c\u8d1d\u65af\u5728\u5404\u81ea\u7684 Dorian \u91cc\u8dd1\uff0c\u65cb\u5f8b\u4ece\u548c\u5f26 MIDI \u91cc\u5220\u51fa\u6765\u3002\u53e6\u9644 Dorian \u97f3\u9636\u5e73\u79fb\u7684\u5171\u540c\u97f3\u6570\u8868\u3002",
