   "sum": "\u8fdb\u884c\u4e0d\u9700\u8981\u66f4\u591a\u548c\u5f26\uff0c\u53ea\u9700\u8981\u66f4\u591a\u6392\u5217\u3002E \u5c0f\u8c03\u7684 i\u3001iv \u7528\u8df3\u623f\u5b50\u53e0\u5230 Em11\u3001Am11\uff0c\u518d\u7528\u79fb\u52a8\u3001\u590d\u5236\u3001\u7701\u7565\u505a\u51fa\u56db\u4e2a\u6392\u5217\uff1a\u6839\u97f3\u5168\u90e8\u4e0b\u79fb\u5f53\u4f4e\u97f3\uff0c\u5148\u5b9a\u9876\u97f3\u518d\u5012\u63a8\uff0c\u9876\u97f3\u53e0\u4f4e\u516b\u5ea6\u628a\u6392\u5217\u5305\u8d77\u6765\uff0c\u4e09\u56db\u4e2a\u76f8\u90bb\u97f3\u7ed9\u51fa\u6c34\u5f69\u822c\u7684\u6a21\u7cca\u3002\u9876\u97f3 F\u266f \u2192 G \u2192 A \u2192 B \u722c\u697c\u68af\uff1b\u7b2c\u4e00\u4e2a Am11 \u7701\u6389\u4e94\u97f3\uff0c\u628a\u6ee1\u683c\u7684 B C D E \u7559\u5230\u6700\u540e\u3002\u8282\u594f\u4e0a Am11 \u63d0\u524d\u5230 4&\uff0c\u6bcf\u4e2a\u548c\u5f26\u7b2c\u4e00\u5c0f\u8282\u5728 2&\u30013&\u30014e \u91cd\u590d\uff0c\u7b2c\u4e8c\u5c0f\u8282\u5728 1a\u30012&\uff1b\u7a7a\u6863\u53ea\u7528\u6392\u5217\u91cc\u7684\u97f3\u5199\u88c5\u9970\uff0c\u6700\u540e\u4e00\u5c0f\u8282\u957f\u97f3\u722c\u5230\u9876\u70b9\u3002\u9f13\u5168\u90e8\u4ece\u94a2\u7434\u63a8\u51fa\u6765\uff1aride \u529b\u5ea6\u56db\u5206 > \u516b\u5206 > \u5341\u516d\u5206\u3001\u4e09\u4e2a\u7740\u9646\u70b9\u7528\u9572\u8fb9 + splash\uff1b\u5927\u9f13\u6293\u5207\u5206\u518d\u7ffb\u6eda\u843d\u5730\uff0c\u5f00\u653e\u5927\u9f13\u5f53\u9b3c\u97f3\uff1brim\u3001\u519b\u9f13\u9b3c\u97f3\u548c rim shot \u90fd\u5bf9\u9f50\u94a2\u7434\u3002\u8d1d\u65af\u7ee7\u627f\u94a2\u7434\u6839\u97f3\u7684\u8282\u594f\uff0c\u52a0\u516b\u5ea6\u3001V\u2013I\u3001E \u6301\u7eed\u97f3\u3001\u4e0a\u4e0b\u90bb\u97f3\u548c X \u97f3\u3002",
