   "sum": "\u65cb\u5f8b\u97f3\u6bd4\u548c\u5f26\u91cc\u67d0\u4e2a\u97f3\u9ad8 13 \u4e2a\u534a\u97f3\uff08\u5c0f\u4e5d\u5ea6\uff0c\u9694\u4e00\u4e2a\u516b\u5ea6\u7684\u5c0f\u4e8c\u5ea6\uff09\u4f1a\u6301\u7eed\u5730\u78e8\uff1aA \u5c0f\u8c03 Am9 \u2192 Dm9 \u4e0a\uff0cDm9 \u7684 9 \u97f3 E3 \u548c\u65cb\u5f8b\u7684 F4 \u90fd\u201c\u6b63\u786e\u201d\uff0c\u653e\u4e00\u8d77\u5374\u8ba9\u4eba\u5faa\u73af\u4e24\u5206\u949f\u5c31\u60f3\u5207\u6b4c\uff0c\u8f6c\u4f4d\u4e5f\u6551\u4e0d\u4e86\u3002\u5148\u7528\u534a\u97f3\u8868\u8ba4\u97f3\u7a0b\uff08\u5e76\u5206\u6e05\u201c\u5c0f\u4e5d\u5ea6\u97f3\u7a0b\u201d\u548c\u201cm9 \u548c\u5f26\u201d\uff09\uff0c\u518d\u7ed9\u4e09\u79cd\u89e3\u6cd5\uff1a\u628a F \u6362\u6210 G\uff1b\u4fdd\u7559 F \u4f46\u8ba9\u5b83\u5f53\u77ed\u53e5\u91cc\u7684\u7ecf\u8fc7\u97f3\uff08G F E / F G E \u4e00\u95ee\u4e00\u7b54\uff0c\u518d\u52a0\u5341\u516d\u5206\u548c\u6a21\u8fdb\uff09\uff1b\u65cb\u5f8b\u4e0d\u52a8\uff0c\u628a Dm9 \u4e34\u65f6\u4e0a\u79fb\u534a\u97f3\u6210 E\u266dm9\uff0cE \u53d8 F \u548c\u65cb\u5f8b\u6210\u516b\u5ea6\uff0c\u50cf\u51cf\u901f\u5e26\u3002\u6700\u540e\u56db\u904d\u5faa\u73af\u8f6e\u6d41\u7528\u4e09\u79cd\u89e3\u6cd5\uff0c\u672b\u62cd\u52a0\u4e00\u4e2a E7(\u266f9\u266d13)\u3002",
